local Players = game:GetService("Players") local RunService = game:GetService("RunService") local Workspace = game:GetService("Workspace") local LocalPlayer = Players.LocalPlayer local Cam = Workspace.CurrentCamera local module = { Config = { on = false, fov = 150, team = false, vis = false, wall = false, sFov = false, }, TargetPart = nil, WallTargetPart = nil, } local WallParams = RaycastParams.new() WallParams.FilterType = Enum.RaycastFilterType.Include local VisParams = RaycastParams.new() VisParams.FilterType = Enum.RaycastFilterType.Exclude local oldRaycast = hookfunction(Workspace.Raycast, newcclosure(function(self, origin, direction, raycastParams) if module.Config.on and module.TargetPart and module.TargetPart.Parent then if typeof(origin) == "Vector3" and typeof(direction) == "Vector3" then local mag = direction.Magnitude if mag < 1 then mag = 1000 end local newDir = (module.TargetPart.Position - origin).Unit * mag if module.Config.wall then WallParams.FilterDescendantsInstances = {module.TargetPart.Parent} return oldRaycast(self, origin, newDir, WallParams) else return oldRaycast(self, origin, newDir, raycastParams) end end end return oldRaycast(self, origin, direction, raycastParams) end)) function module.OriginalRaycast(origin, direction, params) return oldRaycast(Workspace, origin, direction, params) end local function IsVisible(part) if not LocalPlayer.Character then return false end VisParams.FilterDescendantsInstances = {LocalPlayer.Character, part.Parent} local res = Workspace:Raycast(Cam.CFrame.Position, part.Position - Cam.CFrame.Position, VisParams) return not res end local function GetTarget() if not module.Config.on then return nil, nil end local center = Vector2.new(Cam.ViewportSize.X / 2, Cam.ViewportSize.Y / 2) local bestDist = module.Config.fov local bestTarget = nil local wallDist = module.Config.fov local wallTarget = nil for _, p in ipairs(Players:GetPlayers()) do if p ~= LocalPlayer and p.Character and p.Character:FindFirstChild("Head") and p.Character:FindFirstChild("Humanoid") and p.Character.Humanoid.Health > 0 then if module.Config.team and p.Team == LocalPlayer.Team then continue end local head = p.Character.Head local screenPos, onScreen = Cam:WorldToViewportPoint(head.Position) if onScreen then local dist = (Vector2.new(screenPos.X, screenPos.Y) - center).Magnitude if dist < bestDist then local canAim = module.Config.wall or IsVisible(head) if canAim then bestDist = dist bestTarget = head end end if not module.Config.wall and not module.Config.vis and dist < wallDist then wallDist = dist wallTarget = head end end end end if wallTarget and IsVisible(wallTarget) then wallTarget = nil end return bestTarget, wallTarget end task.spawn(function() while true do if module.Config.on then module.TargetPart, module.WallTargetPart = GetTarget() else module.TargetPart = nil module.WallTargetPart = nil end task.wait(0.03) end end) return module
